import{_ as e,o,c as t,a2 as r}from"./chunks/framework.CjAa9jTu.js";const i="/unit_devlab_cortex_m_examples/py32f003/uart.png",g=JSON.parse('{"title":"Comunicación UART","description":"","frontmatter":{},"headers":[],"relativePath":"py32f003-getting-started/66_communication.md","filePath":"py32f003-getting-started/66_communication.md"}'),n={name:"py32f003-getting-started/66_communication.md"};function c(l,a,d,s,p,m){return o(),t("div",null,[...a[0]||(a[0]=[r('<h1 id="comunicacion-uart" tabindex="-1">Comunicación UART <a class="header-anchor" href="#comunicacion-uart" aria-label="Permalink to &quot;Comunicación UART&quot;">​</a></h1><h2 id="del-microcontrolador-a-la-computadora" tabindex="-1">Del microcontrolador a la computadora <a class="header-anchor" href="#del-microcontrolador-a-la-computadora" aria-label="Permalink to &quot;Del microcontrolador a la computadora&quot;">​</a></h2><p>UART permite intercambiar bytes por <strong>TX</strong> y <strong>RX</strong>, con una velocidad acordada entre los extremos. En el paquete <strong>UNIT Electronics PY32 0.1.7</strong>, la instancia genérica <code>Serial</code> utiliza <strong>PA0 como TX</strong> y <strong>PA1 como RX</strong>.</p><table tabindex="0"><thead><tr><th>Placa DevLab</th><th>Adaptador USB-UART de 3.3 V</th></tr></thead><tbody><tr><td>PA0 / TX</td><td>RX</td></tr><tr><td>PA1 / RX</td><td>TX</td></tr><tr><td>GND</td><td>GND</td></tr></tbody></table><p><img src="'+i+'" alt="Referencia de conexiones UART de Development Board"></p><p>Mantén la alimentación de la estación por su fuente habitual. Conecta sólo las señales y GND del adaptador USB-UART; su salida VCC no es necesaria.</p><h2 id="configuracion-en-arduino-ide" tabindex="-1">Configuración en Arduino IDE <a class="header-anchor" href="#configuracion-en-arduino-ide" aria-label="Permalink to &quot;Configuración en Arduino IDE&quot;">​</a></h2><ol><li>Selecciona <strong>U(S)ART support → Enabled (generic &#39;Serial&#39;)</strong>.</li><li>Compila y carga la <a href="./../examples/lab03-uart">práctica de eco</a> por SWD.</li><li>Selecciona el puerto del adaptador USB-UART en el monitor serie.</li><li>Configura <strong>115200 baudios</strong>, 8 bits, sin paridad y un bit de parada (8N1).</li><li>Escribe un texto y comprueba que regresa.</li></ol><div class="info custom-block"><p class="custom-block-title">Dos interfaces distintas</p><p>El cable USB del programador CMSIS-DAP permite cargar firmware. Los mensajes de <code>Serial</code> salen por PA0/PA1: necesitas un adaptador USB-UART o una función UART explícitamente compatible y habilitada en tu programador.</p></div><p>La velocidad de 115200 baudios es la elegida para el ejercicio; no representa por sí sola el límite del periférico. El programa repite un mensaje de estado para que también puedas observarlo al abrir el monitor después del arranque.</p><p><strong>Ejemplo completo:</strong> <a href="./../examples/lab03-uart">Lab 3: Comunicación UART</a>.</p>',11)])])}const b=e(n,[["render",c]]);export{g as __pageData,b as default};
